using System.Text;

namespace Gojo.Experiments.QualitativeFrieze;

public static partial class JunctionInterpretationExperiment
{
    private static string Html(string data) => """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Junctions and possible interpretations · Gojo</title><style>
*{box-sizing:border-box}:root{--ink:#27454a;--muted:#6a766e;--paper:#fbf8ef;--edge:#d7d6c7;--gold:#b97635;--plum:#a45c85}body{margin:0;background:#eeeee2;color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1530px;margin:auto;padding:40px 28px 70px}header{max-width:1050px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:#9b6841}h1{font:clamp(32px,4vw,50px)/1.15 Georgia,serif;margin:12px 0 20px}h2{font:29px/1.2 Georgia,serif;margin:10px 0}h3{font-size:15px;font-weight:650;margin:0 0 10px}p{margin:10px 0 16px}.lede{font-size:19px}.nav{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0 30px}.nav a{border:1px solid var(--edge);border-radius:20px;padding:6px 13px;background:var(--paper);text-decoration:none;font-size:14px}a{color:#246a70;text-underline-offset:3px}.legend{background:#e1e6d9;border-left:3px solid #849465;padding:15px 20px;max-width:1100px;margin:25px 0 35px}.case{margin:35px 0 50px;scroll-margin-top:20px}.case>p{max-width:1050px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.panel{min-width:0;background:var(--paper);border:1px solid var(--edge);padding:20px}.panel img{width:100%;height:auto;display:block}.picture-link{display:block}dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin:15px 0 0;border-top:1px solid var(--edge);padding-top:13px}dt{font-size:11px;line-height:1.3;color:var(--muted)}dd{font-size:22px;margin:2px 0}.support{font-size:13px;color:var(--muted);min-height:45px;margin-top:13px}.hypothesis-choice{display:block;width:100%;font:13px system-ui;padding:8px;border:1px solid #b5b9a8;background:#fffdf7;color:var(--ink);margin-top:12px}.status{font-size:13px;line-height:1.4;padding:9px 11px;background:#f1e7d3;border-left:3px solid var(--gold);margin:12px 0}.status.open{border-color:var(--plum);background:#eee4e9}.alternatives{font-size:13px;color:var(--muted)}details{border-block:1px solid var(--edge);padding:14px 0;margin:30px 0}summary{cursor:pointer;font-weight:650}li{margin:7px 0}.footer{font-size:14px;color:var(--muted);border-top:1px solid var(--edge);padding-top:20px}.comparison{font-size:13px}svg{max-width:100%}@media(max-width:950px){.triptych{grid-template-columns:1fr}.panel{padding:16px}.panel img{max-height:300px;object-fit:contain}.support{min-height:0}main{padding:25px 16px}.nav{gap:7px}.nav a{font-size:13px}}
</style></head><body><main><header><span class="eyebrow">Gojo · local evidence and competing readings</span><h1>Where a line meets another<br>is a question.</h1><p class="lede">The same visible support can describe independent strands, a shared junction, or an interrupted continuation. These examples separate what the source actually connects from what a local cue makes worth considering.</p><p>Solid dots mark actual shared sites; hollow dots mark endpoints. Dashed gold rings mark projected cues without creating sites. In candidate views, purple dashes propose a continuation and orange proposes a front/back order. Every proposal remains unresolved.</p><nav class="nav"><a href="overview.html">All examples together</a><a href="diagnostics.json">Captured query evidence</a><a href="junctions.gojo.json.gz">Native Gojo archive</a><a href="../construction-contexts/gallery.html">Construction contexts</a></nav></header>
<div class="legend"><strong>Keep the questions separate:</strong> does it share a site, continue as a strand, sit in front of another, belong to one object, or permit transfer? A useful cue for one question does not answer all the others.<p>Open read evidence counts missing or unresolved cue reads. A completely supported cue can still have several open interpretations.</p></div><div id="cases"></div><details><summary>What this round establishes and leaves open</summary><ul id="limits"></ul><p>Inputs expose native sites, strokes, formal unmeasured words and actual incidence. No renderer coordinates or image parsing feed the reader. The source is never rewritten when a candidate is selected.</p><p>Junction cues can support completion, while context can change the interpretation. See <a href="https://bpb-us-e1.wpmucdn.com/sites.dartmouth.edu/dist/9/2172/files/2020/01/2.pdf">Tse and Albert (1998)</a>. Our proposal rules are a bounded engineering experiment rather than a model of human perception.</p></details><footer class="footer"><p id="native-summary"></p><p>Connection counts name their basis: sites with multiple incident strokes, incident stroke pairs, connected source components, or components under an explicitly selected observational continuation. None supplies a material transfer law.</p><p><a href="overview.html">Overview</a> · <a href="diagnostics.json">Diagnostics</a> · <a href="junctions.gojo.json.gz">Native archive</a></p></footer><script id="data" type="application/json">__DATA__</script><script>
'use strict';const model=JSON.parse(document.querySelector('#data').textContent),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const facts=entries=>entries.map(([k,v])=>`<div><dt>${escape(k)}</dt><dd>${v}</dd></div>`).join('');
for(const item of model.cases){const article=document.createElement('article');article.className='case';article.dataset.case=item.id;article.id=item.id;
 const s=item.sourceFacts,f=item.inferenceFacts,peers=model.cases.filter(peer=>peer.id!==item.id&&peer.comparisonGroup===item.comparisonGroup);
 article.innerHTML=`<span class="eyebrow">${escape(item.id)} · local read</span><h2>${escape(item.name)}</h2><p>${escape(item.description)}</p><p class="comparison">${peers.map(peer=>`Compare <a href="gallery.html?case=${peer.id}">${escape(peer.id+' · '+peer.name)}</a>`).join(' · ')}</p><div class="triptych"><section class="panel"><h3>Observed drawing</h3><a class="picture-link" href="${item.source}"><img src="${item.source}" alt="${escape(item.name)} observed drawing"></a><p class="support">Equal visible support can preserve different endpoint identities and actual connections.</p><dl class="observation-facts">${facts([['Actual strokes',s.strokes],['Actual site roles',s.sites],['Native numbers',0]])}</dl></section><section class="panel"><h3>What the source actually connects</h3><a class="picture-link" href="${item.actual}"><img src="${item.actual}" alt="${escape(item.name)} actual shared site topology"></a><p class="support">Solid dots are actual shared sites; endpoint coincidence alone supplies no connection.</p><dl class="source-facts">${facts([['Sites with ≥2 strokes',s.joinedSites],['Incident stroke pairs',s.strokePairConnections],['Source components',s.components],['Endpoints',s.endpoints],['T / Y / X',s.t+' / '+s.y+' / '+s.x],['Nonstraight 2-ray sites',s.l]])}</dl></section><section class="panel hypothesis"><h3>Cues and possible interpretations</h3><a class="picture-link candidate-link"><img class="candidate-image" alt=""></a><label><span class="alternatives">Inspect a reading</span><select class="hypothesis-choice" aria-label="${escape(item.id)} interpretation"></select></label><p class="status"></p><p class="support candidate-description"></p><dl class="candidate-facts"></dl></section></div>`;
 const choice=article.querySelector('.hypothesis-choice');choice.add(new Option('Cue evidence only','-1'));item.candidates.forEach((candidate,index)=>choice.add(new Option(`${index+1}. ${candidate.name}`,String(index))));
 function update(){const index=Number(choice.value),candidate=item.candidates[index],src=candidate?candidate.image:item.cues;
  article.dataset.hypothesis=candidate?candidate.id:'cues';article.querySelector('.candidate-image').src=src;article.querySelector('.candidate-image').alt=`${item.id}: ${candidate?candidate.name:'cue evidence only'}`;article.querySelector('.candidate-link').href=src;
  const status=article.querySelector('.status');status.className='status'+(candidate||f.open?' open':'');
  status.textContent=candidate?'Open hypothesis · source remains unchanged':f.open?`${f.open} open evidence items · a missing read is not a negative finding`:item.candidates.length?`${item.candidates.length} candidate readings retained`:'No candidate proposed by this bounded reader';
  article.querySelector('.candidate-description').textContent=candidate?`${candidate.bridgeCount} proposed continuations · ${candidate.cutCount} retained cut endpoints · ${candidate.depthCount} proposed depth orders. Components under this observational reading: ${candidate.virtualComponents}; actual source: ${s.components}.`:'A strict crossing is interior to both strokes; projected endpoint contact is a separate cue. Neither creates a shared site.';
  article.querySelector('.candidate-facts').innerHTML=facts([['Strict projected crossings',f.strictCrossings],['Projected endpoint contacts',f.projectedContacts],['Facing collinear gaps',f.facingGaps],['Candidate readings',f.candidates],['Blocked cue evidence',f.blocked],['Open read evidence',f.open]]);
 }
 choice.addEventListener('change',update);choice.value=item.candidates.length?'0':'-1';update();document.querySelector('#cases').append(article);
}
document.querySelector('#limits').innerHTML=model.limits.map(s=>`<li>${escape(s)}</li>`).join('');document.querySelector('#native-summary').textContent=`${model.cases.length} authored source cases · ${model.nativeElements.toLocaleString()} captured native participants · ${model.nativeNumericElements} numeric participants · native archive round-trip verified.`;
const requested=new URLSearchParams(location.search).get('case');if(requested)document.getElementById(requested)?.scrollIntoView();
</script></main></body></html>
""".Replace("__DATA__", data);

    private static string Overview(IReadOnlyList<CaseModel> models)
    {
        var html = new StringBuilder("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Junction interpretations · all examples</title><style>*{box-sizing:border-box}body{background:#eeeee2;color:#27454a;font:15px/1.5 system-ui;margin:0}main{max-width:1500px;margin:auto;padding:30px}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:38px}h2{font-size:25px}.row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}figure{background:#fbf8ef;border:1px solid #d7d6c7;padding:12px;margin:0}img{width:100%;height:auto;display:block}figcaption{font-size:13px}a{color:#246a70}article{margin:30px 0 45px}article>p{max-width:1100px}@media(max-width:750px){main{padding:20px 15px}.row{grid-template-columns:1fr}}</style></head><body><main><h1>Junctions · source, cues, interpretation</h1><p><a href='gallery.html'>Interactive readings and alternative candidates</a> · <a href='diagnostics.json'>Evidence</a></p><p>Actual shared sites and projected crossings are separate. Purple dashed continuations and orange foreground strokes depict unresolved proposals. The original source remains available and unchanged.</p>");
        foreach (var item in models)
        {
            var candidate = item.Candidates.FirstOrDefault(); var f = item.InferenceFacts;
            html.Append($"<article><h2>{H(item.Id + " · " + item.Name)}</h2><p>{H(item.Description)}</p><div class='row'><figure><a href='gallery.html?case={item.Id}'><img src='{item.Source}' alt='{H(item.Name + " drawing")}'/></a><figcaption>Observed drawing</figcaption></figure><figure><img src='{item.Actual}' alt='{H(item.Name + " actual topology")}'/><figcaption>{item.SourceFacts.JoinedSites} actual joined sites · {item.SourceFacts.StrokePairConnections} incident stroke pairs · {item.SourceFacts.Components} components</figcaption></figure><figure><img src='{candidate?.Image ?? item.Cues}' alt='{H(item.Name + " interpretation")}'/><figcaption>{f.StrictCrossings} strict projected crossings · {f.ProjectedContacts} endpoint contacts · {f.FacingGaps} gaps · {f.Candidates} candidates · {f.Open} open read evidence</figcaption></figure></div></article>");
        }
        return html.Append("<p><a href='gallery.html'>Inspect all retained alternatives</a> · <a href='junctions.gojo.json.gz'>Native Gojo archive</a></p></main></body></html>").ToString();
    }
}
